import mujoco, numpy as np, time

REF = open('/app/model_ref.xml').read()

def build(mod=None):
    s = REF
    if mod: s = mod(s)
    return s

def perstep(m, n=200, reps=3):
    d = mujoco.MjData(m)
    mujoco.mj_forward(m, d)
    best = 1e9
    for _ in range(reps):
        t = time.perf_counter()
        for _ in range(n):
            mujoco.mj_step(m, d)
        best = min(best, (time.perf_counter()-t)/n)
    return best*1e3

def no_eq(s):
    return s.replace('<connect name="right_boundary" body1="B_last" body2="slider" anchor=".025 0 0"/>','')

def no_plugin(s):
    import re
    s = re.sub(r'<extension>.*?</extension>', '', s, flags=re.S)
    s = re.sub(r'<plugin plugin="mujoco.elasticity.cable">.*?</plugin>', '', s, flags=re.S)
    return s

def small_cable(s):
    return s.replace('count="41 1 1"', 'count="10 1 1"')

def slider_only(s):
    import re
    return re.sub(r'<composite.*?</composite>', '', s, flags=re.S)

cases = [('ref', None), ('no equality', no_eq), ('no plugin', no_plugin),
         ('cable count 10', small_cable), ('no cable at all', slider_only)]
for name, mod in cases:
    try:
        m = mujoco.MjModel.from_xml_string(build(mod))
        mj = perstep(m)
        print('%-18s nbody=%3d nq=%3d nv=%3d nefc_total | per-step %.4f ms' % (name, m.nbody, m.nq, m.nv, mj), flush=True)
    except Exception as e:
        print('%-18s ERROR %s' % (name, str(e).splitlines()[0]), flush=True)
EOF
timeout 600 python3 -u diag.py
